import{_ as t,a,o,a4 as d}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse(`{"title":"Configuration Update","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"update-json","title":"Update — JSON (scalars)","description":"Bulk-upsert a code → value map under a slug. Returns the re-resolved values.","query":"curl -X POST \\"https://your-domain.com/api/admin/configuration\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d '{\\n    \\"slug\\": \\"sales.order_settings\\",\\n    \\"channel\\": \\"default\\",\\n    \\"locale\\": \\"en\\",\\n    \\"values\\": {\\n      \\"sales.order_settings.reorder.admin\\": \\"1\\",\\n      \\"sales.order_settings.reorder.shop\\": \\"0\\"\\n    }\\n  }'\\n","response":"{\\n  \\"success\\": true,\\n  \\"message\\": \\"Configuration updated successfully.\\",\\n  \\"slug\\": \\"sales.order_settings\\",\\n  \\"channel\\": \\"default\\",\\n  \\"locale\\": \\"en\\",\\n  \\"values\\": {\\n    \\"sales.order_settings.reorder.admin\\": \\"1\\",\\n    \\"sales.order_settings.reorder.shop\\": \\"0\\"\\n  }\\n}\\n"},{"id":"update-multipart","title":"Update — multipart (file upload)","description":"Image / file fields must be sent as multipart/form-data. Mixed scalars + files are allowed in one request.","query":"curl -X POST \\"https://your-domain.com/api/admin/configuration\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -F \\"slug=general.design.admin_logo\\" \\\\\\n  -F \\"channel=default\\" \\\\\\n  -F \\"locale=en\\" \\\\\\n  -F \\"values[general.design.admin_logo.logo_image]=@/path/to/logo.png\\"\\n","response":"{\\n  \\"success\\": true,\\n  \\"message\\": \\"Configuration updated successfully.\\",\\n  \\"slug\\": \\"general.design.admin_logo\\",\\n  \\"channel\\": \\"default\\",\\n  \\"locale\\": \\"en\\",\\n  \\"values\\": {\\n    \\"general.design.admin_logo.logo_image\\": \\"configuration/abc123.png\\"\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/configuration/update.md","filePath":"api/rest-api/admin/configuration/update.md","lastUpdated":1783079210000}`),s={name:"api/rest-api/admin/configuration/update.md"};function n(i,e,r,l,c,u){return o(),a("div",null,e[0]||(e[0]=[d('<h1 id="configuration-update" tabindex="-1">Configuration Update <a class="header-anchor" href="#configuration-update" aria-label="Permalink to &quot;Configuration Update&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/configuration</code></td><td>POST</td></tr></tbody></table><p>Bulk-upserts every entry in <code>values</code> under the given <code>slug</code>. On success the response returns the freshly-resolved values for that slug (the same shape as the <a href="./values.html">Values</a> endpoint), so the client can refresh its form state without a follow-up read. See the <a href="./">Configuration overview</a> for the full flow.</p><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><p>Accepts <code>application/json</code> (for scalar fields) or <code>multipart/form-data</code> (when uploading <code>image</code> / <code>file</code> fields). Mixed payloads — some scalars and some files — are supported in a single multipart request.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>slug</code></td><td>string</td><td><strong>Required.</strong> The slug whose subtree is being written.</td></tr><tr><td><code>channel</code></td><td>string</td><td>Channel code. Defaults to the default channel.</td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale code. Defaults to the app locale.</td></tr><tr><td><code>values</code></td><td>object</td><td>Map of <code>code → value</code>. <strong>Every key must start with <code>slug.</code>.</strong></td></tr></tbody></table><p>For multipart, file parts use <code>values[&lt;code&gt;]</code> as the field name — for example <code>values[general.design.admin_logo.logo_image]</code>. Uploaded files are stored and the resulting storage path is written as the field&#39;s value.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Each field&#39;s validation rules come from the schema (discovered via <a href="./menu.html">Menu</a>), resolved and enforced on the server — they are never trusted from the client. Call Menu first to know which rules apply to a given code.</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p>Requires the admin role to carry <code>configuration</code> (or the finer-grained <code>configuration.edit</code>), or <code>permission_type = &quot;all&quot;</code>.</p><h2 id="response-codes" tabindex="-1">Response codes <a class="header-anchor" href="#response-codes" aria-label="Permalink to &quot;Response codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>200</td><td>Updated. Body returns the freshly-resolved values.</td></tr><tr><td>401</td><td>Unauthenticated.</td></tr><tr><td>403</td><td>Missing the <code>configuration</code> permission.</td></tr><tr><td>404</td><td>Slug not registered.</td></tr><tr><td>422</td><td>Validation failed, out-of-scope key, missing <code>slug</code> / <code>values</code>, or an attempt to write a custom (blade) field.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Stay in scope</p><p>Every key in <code>values</code> must start with the supplied <code>slug.</code> prefix. A request with <code>slug: &quot;sales.order_settings&quot;</code> cannot write <code>catalog.inventory.stock_threshold</code> even if the fully-qualified key is supplied — the server rejects it with the offending key before any write happens.</p></div><div class="warning custom-block"><p class="custom-block-title">File / image fields are multipart-only</p><p>JSON (and GraphQL) cannot carry binaries. To set an <code>image</code> / <code>file</code> field, send <code>multipart/form-data</code> with the file at <code>values[&lt;code&gt;]</code>.</p></div><div class="warning custom-block"><p class="custom-block-title">Custom fields are read-only</p><p>Fields whose schema declares <code>type: &quot;custom&quot;</code> (blade-rendered in the admin) cannot be written via the API.</p></div><div class="warning custom-block"><p class="custom-block-title">Password fields are stored plaintext</p><p><code>type: &quot;password&quot;</code> fields are UI-masking only; the value is stored as plaintext. This is a Bagisto core behaviour, not an API limitation.</p></div>',17)]))}const g=t(s,[["render",n]]);export{h as __pageData,g as default};
